#include <algorithm>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    const vector<string> notes = {
        "C", "C#", "D", "D#", "E", "F",
        "F#", "G", "G#", "A", "B", "H"
    };

    vector<string> chord(3);
    cin >> chord[0] >> chord[1] >> chord[2];

    sort(chord.begin(), chord.end());

    do {
        vector<int> index(3);

        for (int i = 0; i < 3; ++i) {
            index[i] = find(notes.begin(), notes.end(), chord[i]) - notes.begin();
        }

        int firstInterval = (index[1] - index[0] + 12) % 12;
        int secondInterval = (index[2] - index[1] + 12) % 12;

        if (firstInterval == 3 && secondInterval == 4) {
            cout << "minor\n";
            return 0;
        }

        if (firstInterval == 4 && secondInterval == 3) {
            cout << "major\n";
            return 0;
        }
    } while (next_permutation(chord.begin(), chord.end()));

    cout << "strange\n";
    return 0;
}

