        {"G#", 8}, {"A", 9}, {"B", 10}, {"H", 11}
    };

    vector<string> notes(3);
    cin >> notes[0] >> notes[1] >> notes[2];

    sort(notes.begin(), notes.end());

    do {
        int first = noteIndex.at(notes[0]);
        int second = noteIndex.at(notes[1]);
        int third = noteIndex.at(notes[2]);

        int interval1 = (second - first + 12) % 12;
        int interval2 = (third - second + 12) % 12;

        if (interval1 == 3 && interval2 == 4) {
            cout << "minor\n";
            return 0;
